/* Daily management lists over the offline ledger; examples stay separate from submitted conversations. */
(() => {
  'use strict';
  const root=document.querySelector('#configuration-root'),J=window.ReviewJourney;
  const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const modeNames={confirm:'本人确认',auto_readonly:'自动只读',approval:'逐次审批',collect_only:'仅收集',blocked:'已阻止'};
  const states={waiting:['待本人确认','muted'],pending:['待审批','pending'],approved:['已批准','success'],rejected:['已拒绝','danger'],expired:['已失效','muted'],policy:['自动授权','neutral']};
  const views={approvals:{query:'',filter:'pending',scope:'all',source:'auto',page:1},executions:{query:'',filter:'all',scope:'all',source:'auto',page:1}};
  const reasons={},pageSize=8;
  let opened=null,returnFocus=null,lastPage=null;
  const at=minutes=>new Date(Date.now()-minutes*60000).toISOString();
  const examples=[
    {id:'sample-approval-1',title:'报表金额与明细不一致',ownerName:'林晓 · 示例',scope:'orders-test',status:'pending',createdAt:at(8),reason:'核对昨日订单报表和明细，定位差异订单。',requestedModel:'默认排查模型',readonly:true},
    {id:'sample-approval-2',title:'订单接口超时检查',ownerName:'陈宇 · 示例',scope:'orders-stage',status:'pending',createdAt:at(23),reason:'按请求标识关联只读日志，确认首个超时位置。',requestedModel:'默认排查模型',readonly:true},
    {id:'sample-approval-3',title:'订单状态同步延迟',ownerName:'周宁 · 示例',scope:'orders-test',status:'pending',createdAt:at(46),reason:'比较事件时间与报表刷新时间，确认数据延迟。',requestedModel:'默认排查模型',readonly:true},
    {id:'sample-approval-4',title:'检查退款汇总口径',ownerName:'林晓 · 示例',scope:'orders-test',status:'approved',createdAt:at(110),reason:'读取汇总说明与脱敏明细，核对统计口径。',requestedModel:'默认排查模型',readonly:true},
    {id:'sample-approval-5',title:'核对订单导出文件',ownerName:'陈宇 · 示例',scope:'orders-stage',status:'rejected',createdAt:at(150),reason:'缺少导出时间范围，需补充后提交新计划。',requestedModel:'默认排查模型',readonly:true}
  ];
  const taskExamples=[
   ['sample-task-1','报表金额与导出明细不一致','林晓 · 示例','orders-stage','approval','待审批'],
   ['sample-task-2','订单接口超时排查','陈宇 · 示例','orders-test','running','执行中 · 示例'],
   ['sample-task-3','检索付款回调错误日志','周宁 · 示例','orders-test','blocked','异常待处理'],
   ['sample-task-4','订单统计口径核对','林晓 · 示例','orders-stage','done','待用户验证'],
   ['sample-task-5','历史订单状态说明','陈宇 · 示例','orders-test','done','已确认 · 示例'],
   ['sample-task-6','核对月度汇总附件','周宁 · 示例','orders-test','collect','仅收集'],
   ['sample-task-7','补充差异订单范围','林晓 · 示例','orders-test','waiting','待补充'],
   ['sample-task-8','核查原执行回执','陈宇 · 示例','orders-stage','blocked','原执行核查中']
  ].map(([id,title,ownerName,scope,taskState,taskLabel],i)=>({id,title,ownerName,scope,taskState,taskLabel,status:'example',createdAt:at(8+i*18),reason:'用于任务列表与详情评审的独立合成案例，未提交真实执行。'}));
  const allowed=actor=>['operator','approver','support'].includes(actor);
  const scopeName=id=>({'orders-test':'订单系统 / 测试','orders-stage':'订单系统 / 预发'}[id]||id);
  const person=id=>J.users.find(x=>x.id===id)?.name?.replace('（合成测试人员）','').replace('（合成协作成员）','')||id;
  const date=value=>value?new Date(value).toLocaleString('zh-CN',{timeZone:'Asia/Shanghai',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',hour12:false}):'—';
  const button=(action,label,disabled=false,extra='')=>`<button type="button" data-ops="${action}" ${disabled?'disabled':''} ${extra}>${label}</button>`;
  function records(actor){return allowed(actor)?J.records().filter(r=>['orders-test','orders-stage'].includes(r.scope)):[];}
  function group(r){return r.pendingApproval?'approval':r.binding?.state==='active_simulation'?'running':r.status==='仅收集'?'collect':r.status==='执行已阻止'||r.status==='审批拒绝'?'blocked':r.resultRevision&&r.resultInputRevision===r.inputRevision?'done':'waiting';}
  const processed=x=>['approved','rejected','expired','policy'].includes(x.state);
  function approvalState(a){return a.pendingReview?'pending':a.decision==='待确认'?'waiting':/拒绝/.test(a.decision)?'rejected':/批准|已允许/.test(a.decision)?'approved':/自动/.test(a.decision)?'policy':'expired';}
  function liveRows(page,actor){return records(actor).flatMap(r=>page==='executions'?[{key:r.id,id:r.id,r,title:r.title,ownerName:person(r.owner),scope:r.scope,state:group(r),status:r.status,createdAt:r.trace?.[0]?.at}]:[
    ...(r.approvalHistory||[]).map(a=>({key:r.id+'::'+a.contextId,id:r.id,r,a,title:r.title,ownerName:person(r.owner),scope:r.scope,state:approvalState(a),createdAt:a.createdAt||r.trace?.[0]?.at})),
    ...(r.executions||[]).filter(x=>x.authority==='policy').map(x=>({key:r.id+'::policy::'+x.id,id:r.id,r,a:{contextId:x.contextRef,decision:'按已授权只读策略自动放行（非人工审批）',preparation:x.preparationSnapshot||null,inputRevision:x.inputRevision},title:r.title,ownerName:person(r.owner),scope:r.scope,state:'policy',createdAt:r.trace?.[0]?.at}))
  ]).reverse();}
  function data(page,actor){const v=views[page],live=liveRows(page,actor),sample=allowed(actor)&&(v.source==='examples'||v.source==='auto'&&!live.length);return {sample,items:sample?(page==='executions'?taskExamples:examples).map(x=>({key:x.id,id:x.id,example:x,title:x.title,ownerName:x.ownerName,scope:x.scope,state:page==='approvals'?x.status:x.taskState|| (x.status==='pending'?'approval':x.status==='approved'?'waiting':'blocked'),status:x.taskLabel||(x.status==='pending'?'待审批':x.status==='approved'?'已批准，未执行':'审批拒绝'),createdAt:x.createdAt})):live};}
  const statusTag=(x,page)=>{const [name,tone]=page==='approvals'?states[x.state]||states.expired:[x.status,{running:'neutral',approval:'pending',done:'success',blocked:'danger',collect:'muted',waiting:'muted'}[x.state]||'muted'];return `<span class="ops-status ${tone}">${esc(name)}</span>`;};
  function matches(x,v){return (!v.query||[x.title,x.ownerName,x.id].some(y=>y.toLowerCase().includes(v.query.toLowerCase())))&&(v.scope==='all'||x.scope===v.scope);}
  function view(page,actor){
    if(lastPage!==page){opened=null;lastPage=page;}
    const v=views[page],d=data(page,actor),tabs=page==='approvals'?[['pending','待审批'],['processed','已处理'],['all','全部']]:[['all','全部'],['approval','待审批'],['running','执行中'],['blocked','异常'],['done','待验证 / 已交付']];
    const scoped=d.items.filter(x=>matches(x,v)),filtered=scoped.filter(x=>v.filter==='all'||v.filter==='processed'&&processed(x)||x.state===v.filter),pages=Math.max(1,Math.ceil(filtered.length/pageSize));v.page=Math.min(v.page,pages);
    const visible=filtered.slice((v.page-1)*pageSize,v.page*pageSize),current=d.items.find(x=>x.key===opened);
    const denial=!allowed(actor);
    return `<section class="ops-panel" aria-label="${page==='approvals'?'审批':'执行'}列表"><div class="ops-panel-head"><div class="ops-tabs" role="tablist" aria-label="处理状态">${tabs.map(([id,name])=>`<button type="button" role="tab" aria-selected="${v.filter===id}" data-ops="tab" data-value="${id}">${name}<span>${scoped.filter(x=>id==='all'||id==='processed'&&processed(x)||x.state===id).length}</span></button>`).join('')}</div><span class="ops-source-label">${d.sample?'示例数据':'本次离线提交'}</span></div><div class="ops-filters"><label class="ops-search"><span class="sr-only">搜索申请人或检查事项</span><input type="search" data-ops-field="query" value="${esc(v.query)}" placeholder="搜索申请人、检查事项"><span aria-hidden="true">⌕</span></label><div class="ops-search-actions">${button('search','搜索')}${v.query||v.scope!=='all'?button('reset','重置'):''}</div><label><span class="sr-only">系统环境</span><select data-ops-field="scope"><option value="all">全部环境</option>${['orders-test','orders-stage'].map(id=>`<option value="${id}" ${v.scope===id?'selected':''}>${scopeName(id)}</option>`).join('')}</select></label>${page==='executions'?`<label><span class="sr-only">更多状态</span><select data-ops-field="filter">${[['all','全部状态'],['approval','待审批'],['running','执行中'],['done','已交付'],['collect','仅收集'],['blocked','被阻止 / 拒绝'],['waiting','待补充 / 确认']].map(([id,name])=>`<option value="${id}" ${v.filter===id?'selected':''}>${name}</option>`).join('')}</select></label>`:''}<label class="ops-source"><span class="sr-only">数据来源</span><select data-ops-field="source"><option value="auto" ${v.source==='auto'?'selected':''}>${d.sample?'示例预览':'本次提交'}</option><option value="live" ${v.source==='live'?'selected':''}>仅本次提交</option><option value="examples" ${v.source==='examples'?'selected':''}>示例数据</option></select></label></div><div class="ops-table-wrap"><table class="ops-table"><thead><tr>${(page==='approvals'?['检查事项','申请人','系统 / 环境','状态','提交时间','操作']:['任务 / 问题','系统 · 环境','状态','执行配置','提交人','操作']).map((name,i)=>`<th scope="col" ${i===5?'class="ops-action-col"':''}>${name}</th>`).join('')}</tr></thead><tbody>${visible.map(x=>`<tr data-row-id="${esc(x.id)}"><td class="ops-subject"><strong>${esc(x.title)}</strong><small>${page==='approvals'?'只读检查':esc(modeNames[x.r?.preparation?.executionPolicy?.mode]||'逐次审批')}${x.example?' · 示例':''}${page==='executions'?' · '+esc(x.id):''}</small></td>${page==='approvals'?`<td>${esc(x.ownerName)}</td><td>${esc(scopeName(x.scope))}</td><td>${statusTag(x,page)}</td><td class="ops-date">${date(x.createdAt)}</td>`:`<td>${esc(scopeName(x.scope))}</td><td>${statusTag(x,page)}</td><td>${esc(x.r?.preparation?.requestedModel||'默认检查模型')}<small class="task-config-sub">${esc(modeNames[x.r?.preparation?.executionPolicy?.mode]||'流程预设')} · 未真实调用</small></td><td>${esc(x.ownerName)}</td>`}<td class="ops-action-col">${button('select',page==='approvals'&&x.state==='pending'?'去审批':'查看',false,`data-id="${esc(x.id)}" data-key="${esc(x.key)}" class="ops-link"`)}</td></tr>`).join('')||`<tr><td colspan="6"><div class="ops-empty"><strong>${denial?'当前角色无权查看此列表':d.items.length?'没有匹配的记录':'还没有提交记录'}</strong><p>${denial?'在右上角演示设置中选择审批责任人或执行管理员。':d.items.length?'试试其他状态，或清除筛选条件。':'可先在对话中提交检查，也可切换到示例数据预览。'}</p>${!denial?button('empty-reset','清除筛选'):''}</div></td></tr>`}</tbody></table></div><footer class="ops-list-footer"><span>共 ${filtered.length} 条${d.sample?(page==='approvals'?' · 示例决定不会提交执行':' · 示例任务，不代表真实执行'):''}</span><div>${button('previous','上一页',v.page<=1)}<span>${v.page} / ${pages}</span>${button('next','下一页',v.page>=pages)}</div></footer></section>${current?drawer(current,page,actor):''}`;
  }
  function drawer(x,page,actor){const r=x.r,p=x.a?.preparation||r?.preparation,resources=p?.resources,binding=page==='approvals'?r?.executions?.find(n=>n.contextRef===x.a?.contextId):r?.binding,sample=!!x.example,pending=page==='approvals'&&x.state==='pending',mayApprove=actor==='approver'&&pending;return `<div class="ops-drawer-backdrop"></div><section class="ops-drawer" role="dialog" aria-modal="true" aria-labelledby="ops-detail-title" tabindex="-1"><header><div><span class="ops-kicker">${page==='approvals'?'审批详情':'执行详情'}${sample?' · 示例':''}</span><h2 id="ops-detail-title">${esc(x.title)}</h2></div>${button('close','×',false,'class="ops-close" aria-label="关闭详情"')}</header><div class="ops-drawer-body">${statusTag(x,page)}<dl class="ops-summary"><div><dt>申请人</dt><dd>${esc(x.ownerName)}</dd></div><div><dt>系统 / 环境</dt><dd>${esc(scopeName(x.scope))}</dd></div><div><dt>提交时间</dt><dd>${date(x.createdAt)}</dd></div><div><dt>${page==='approvals'?'审批类型':'执行方式'}</dt><dd>${esc(page==='approvals'?'只读检查':modeNames[p?.executionPolicy?.mode]||'逐次审批')}</dd></div></dl><section class="ops-plan"><h3>本次检查</h3>${p?.approvalSummary?`<div class="ops-request-summary"><strong>问题</strong><p>${esc(p.approvalSummary.question)}</p>${p.approvalSummary.conditions!==p.approvalSummary.question?`<strong>本轮补充</strong><p>${esc(p.approvalSummary.conditions)}</p>`:''}</div>`:''}<p>${esc(sample?x.example.reason:p?.executionPolicy?.reason||'按用户确认的范围检查问题，交付结果后由用户验证。')}</p><ul><li>读取本环境获准的代码、数据和日志</li><li>关联证据并生成核对结果</li><li>不写入业务数据，不修改代码</li></ul></section>${page==='executions'?`<section class="ops-plan"><h3>处理进度</h3><p>${esc(r?.verification?'用户已确认该结果':r?.resultRevision?'结果已交付，等待用户验证':sample?'示例仅展示申请状态，未提交执行。':r?.status||'尚未执行')}</p><p>${r?.binding?.state==='active_simulation'?'当前正在离线模拟执行。':''}</p></section>`:`<p class="ops-hint">${sample?'示例预览：决定仅更新本页状态。':x.state==='policy'?'按已授权只读策略放行，非人工审批。':pending?'批准仅适用于本次固定计划；计划变化后需重新审批。':esc(x.a?.decision||'此事项已处理。')}</p>`}${x.a?.comment?`<div class="ops-approved-comment"><h3>审批意见</h3><p>${esc(x.a.comment)}</p></div>`:''}<details class="ops-technical"><summary>技术详情与审计</summary><dl><dt>会话 / 输入修订</dt><dd>${esc(r?.id||x.id)} / ${esc(x.a?.inputRevision||r?.inputRevision||'示例')}</dd><dt>上下文 / 有效期</dt><dd>${esc(x.a?.contextId||p?.id||'示例快照')} / ${esc(x.a?.validUntil||p?.validUntil||'示例不向后端提交')}</dd><dt>授权依据</dt><dd>${esc(p?.executionPolicy?.policyRef||'示例只读计划')}</dd><dt>固定执行拥有者</dt><dd>${binding?esc(binding.provider+' / '+binding.id+' / '+binding.state):'尚未提交执行'}</dd><dt>资源快照</dt><dd>代码 ${resources?.projects.length||0} / MCP ${resources?.mcps.length||0} / Skill ${resources?.skills.length||0}</dd></dl><p>${esc(JSON.stringify({resources:resources||'示例',context:p?.id,actualModel:'unknown'}))}</p><h3>历次节点执行</h3><ol>${(r?.executions||[]).map(n=>`<li>${esc(n.id)} · 输入 ${n.inputRevision} · ${esc(n.state)} · 结果 ${n.resultRevision||'未交付'}</li>`).join('')||'<li>尚未创建执行</li>'}</ol><h3>操作记录</h3><ol>${(r?.events||[x.example?.decision||'合成待办，仅用于页面预览']).map(e=>`<li>${esc(e)}</li>`).join('')}</ol></details>${pending?`<label class="admin-field">审批意见 <span class="ops-optional">选填，拒绝时必填</span><textarea data-ops-field="reason" rows="3" placeholder="填写补充意见或拒绝原因">${esc(reasons[x.key]||'')}</textarea></label>`:''}<p class="ops-inline-feedback" role="status"></p></div><footer class="ops-drawer-footer">${page==='approvals'?`${pending?button('reject','拒绝',!mayApprove,'class="ops-reject"')+button('approve','批准',!mayApprove,'class="admin-primary"'):button('dismiss','关闭')}`:`${r?button('record','查看用户记录'):''}${button('stop','停止执行',actor!=='operator'||r?.binding?.state!=='active_simulation')}`}</footer></section>`;}
  function refresh(){window.ServiceDesignPrototype.render(root.dataset.servicePage);}
  function feedback(message){root.querySelector('#service-feedback').textContent=message;const inside=root.querySelector('.ops-inline-feedback');if(inside)inside.textContent=message;}
  function focusDrawer(){root.querySelector('.ops-close')?.focus();}
  function close(){opened=null;refresh();root.querySelector(`[data-ops=select][data-key="${CSS.escape(returnFocus||'')}"]`)?.focus();}
  root.addEventListener('input',e=>{const page=root.dataset.servicePage;if(!views[page]||root.dataset.mode!=='service')return;if(e.target.dataset.opsField==='query')views[page].query=e.target.value;if(e.target.dataset.opsField==='reason')reasons[opened]=e.target.value;});
  root.addEventListener('keydown',e=>{if(!views[root.dataset.servicePage]||root.dataset.mode!=='service')return;if(e.target.dataset.opsField==='query'&&e.key==='Enter'){e.preventDefault();views[root.dataset.servicePage].query=views[root.dataset.servicePage].query.trim();views[root.dataset.servicePage].page=1;refresh();root.querySelector('[data-ops-field=query]')?.focus();}const drawer=root.querySelector('.ops-drawer');if(!drawer||root.querySelector('#service-dialog[open]'))return;if(e.key==='Escape'){e.preventDefault();close();}if(e.key==='Tab'){const focusable=[...drawer.querySelectorAll('button:not([disabled]),textarea,summary')].filter(x=>x.getClientRects().length);const first=focusable[0],last=focusable.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus();}}});
  root.addEventListener('change',e=>{const v=views[root.dataset.servicePage],key=e.target.dataset.opsField;if(!v||!['filter','scope','source'].includes(key))return;v[key]=e.target.value;v.page=1;opened=null;refresh();});
  root.addEventListener('click',e=>{
    if(e.target.classList.contains('ops-drawer-backdrop')){close();return;}
    const b=e.target.closest('[data-ops]'),page=root.dataset.servicePage;if(!b||root.dataset.mode!=='service'||!views[page])return;
    const action=b.dataset.ops,actor=window.ServiceDesignPrototype.actor(),d=data(page,actor),x=d.items.find(x=>x.key===opened),r=x?.r,dialog=root.querySelector('#service-dialog'),v=views[page];
    if(action==='select'){opened=b.dataset.key;returnFocus=opened;refresh();focusDrawer();return;}
    if(action==='close'||action==='dismiss'){close();return;}
    if(action==='search'){v.query=v.query.trim();v.page=1;opened=null;refresh();root.querySelector('[data-ops-field=query]')?.focus();return;}
    if(action==='tab'){v.filter=b.dataset.value;v.page=1;opened=null;refresh();return;}
    if(action==='reset'||action==='empty-reset'){v.query='';v.filter=page==='approvals'?'all':'all';v.scope='all';v.page=1;refresh();return;}
    if(action==='next'||action==='previous'){v.page+=action==='next'?1:-1;refresh();return;}
    if(action==='record'&&r){opened=null;window.ServiceDesignPrototype.openRecord(r.id);return;}
    if(action==='cancel'){dialog.close();root.querySelector(`[data-ops=${dialog.dataset.origin||'approve'}]`)?.focus();return;}
    if(!x){feedback('当前记录已变化，请重新打开。');return;}
    if(action==='approve'||action==='reject'){
      if(actor!=='approver'||x.state!=='pending'){feedback('无权审批或事项已失效。');return;}
      if(action==='reject'&&(reasons[x.key]||'').trim().length<5){feedback('拒绝需填写至少 5 字的理由。');root.querySelector('[data-ops-field=reason]')?.focus();return;}
      dialog.innerHTML=`<h2 id="service-dialog-title">${action==='approve'?'批准这次检查？':'拒绝这次检查？'}</h2><p>${esc(x.title)}<br>${esc(scopeName(x.scope))} · ${esc(x.ownerName)}</p><p>仅限本次固定只读计划。${x.example?'示例不会提交执行。':''}</p><details><summary>计划引用</summary><p>${esc(x.a?.contextId||x.id)} · 输入修订 ${esc(x.a?.inputRevision||r?.inputRevision||'示例')}</p></details><p>${esc(reasons[x.key]||'无附加意见')}</p><div class="admin-dialog-actions">${button('cancel','返回')}${button('confirm-'+action,action==='approve'?'确认批准':'确认拒绝',false,'class="admin-primary"')}</div>`;dialog.dataset.contextRef=x.a?.contextId||x.id;dialog.dataset.recordId=x.key;dialog.dataset.origin=action;dialog.showModal();return;
    }
    if(action==='confirm-approve'||action==='confirm-reject'){
      if(actor!=='approver'||dialog.dataset.recordId!==x.key){feedback('审批身份或目标已变化。');return;}
      let result;if(x.example){if(x.state!=='pending'){result={ok:false,reason:'示例已处理'};}else{x.example.status=action==='confirm-approve'?'approved':'rejected';x.example.decision=reasons[x.key]||'示例批准';result={ok:true};}}
      else result=action==='confirm-approve'?J.approve(r.id,dialog.dataset.contextRef,reasons[x.key]||''):J.reject(r.id,dialog.dataset.contextRef,reasons[x.key]);
      if(result.ok){opened=null;refresh();feedback(x.example?'已更新示例决定，未提交执行。':'已记录审批决定。');setTimeout(()=>root.querySelector('[role=tab][aria-selected=true]')?.focus(),0);}else{dialog.close();feedback(result.reason);}return;
    }
    if(action==='stop'){if(actor!=='operator'||r?.binding?.state!=='active_simulation'){feedback('没有当前可停止的合成执行。');return;}dialog.innerHTML=`<h2 id="service-dialog-title">停止当前执行？</h2><p>仅停止这条本地模拟。真实外部取消仍需执行拥有者确认。</p><div class="admin-dialog-actions">${button('cancel','返回')}${button('confirm-stop','确认停止')}</div>`;dialog.dataset.recordId=x.key;dialog.dataset.origin='stop';dialog.showModal();return;}
    if(action==='confirm-stop'){if(actor!=='operator'||dialog.dataset.recordId!==x.key)return;const result=J.stop(r.id);refresh();feedback(result.ok?'已停止本次本地模拟。':result.reason);}
  });
  window.ExecutionManagement={view,hide(){opened=null;}};
})();
